#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    cin >> n;

    int digit = n % 10;
    int length = 0;
    while (n > 0) {
        ++length;
        n /= 10;
    }

    int answer = (digit - 1) * 10 + length * (length + 1) / 2;
    cout << answer << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        solve();
    }

    return 0;
}

